<script lang="ts">
  import type { Metric, WidgetType } from './model';
  let { onadd, metrics = [], assets = [] }: { onadd: (type: WidgetType, extra?: Record<string, unknown>) => void; metrics?: Metric[]; assets?: { id: string; name: string }[] } = $props();
  const widgets: [WidgetType, string, string, Record<string, unknown>?][] = [['text','Texte','Aa'],['value','Valeur','42'],['gauge','Jauge demi-cercle','◔'],['ring','Anneau','◉'],['bar','Barre horizontale','▰',{ orientation: 'horizontal' }],['bar','Barre verticale','▥',{ orientation: 'vertical' }],['badge','Badge/état','OK'],['sparkline','Courbe','⌁'],['image','Image','▧'],['animation','Animation','✦']];
</script>
<section><span class="eyebrow">Build</span><h3>Sensors</h3><div class="list">{#each metrics.slice(0, 12) as metric}<button type="button" onclick={() => onadd((metric.recommended_widgets[0] as WidgetType) ?? 'value', { binding: metric.id })}><span>{metric.label}</span><small>{metric.value ?? metric.demo_value ?? '—'} {metric.unit}</small></button>{/each}</div><h3>Widgets</h3><div class="palette">{#each widgets as [type, label, preview, extra]}<button type="button" aria-label={`Ajouter ${label}`} onclick={() => onadd(type, extra)}><b>{preview}</b><span>{label}</span></button>{/each}</div>{#if assets.length}<h3>Media</h3><div class="list">{#each assets as asset}<button type="button" onclick={() => onadd('image', { asset_id: asset.id })}><span>▧ {asset.name}</span></button>{/each}</div>{/if}</section>
